import { and, asc, eq, inArray, isNull, or, sql } from "drizzle-orm";

import { createDb, type AppDb } from "../../../db";
import {
  oauthClient,
  oauthClientResource,
  oauthResource,
  user,
} from "../../../db/auth-schema";
import {
  applicationOauthClients,
  applicationResources,
  applicationRoles,
  applications,
  humanPrincipals,
