  const key = normalizeRoleKey(body.key);
  const name = normalizeName(body.name);
  const description = normalizeDescription(body.description);
  const existing = await database.select({ id: applicationRoles.id }).from(applicationRoles).where(and(eq(applicationRoles.applicationId, applicationId), eq(applicationRoles.key, key))).get();
  if (existing) throw new ApiError(409);
  const roleId = `application-role_${crypto.randomUUID()}`;
