    database.insert(applicationRoles).values({ id: roleId, applicationId, key, name, description, status: "active", createdAt: now, updatedAt: now }),
    applicationAuthzVersionStatement(database, applicationId, now),
    auditStatement(database, `application-role:created:${roleId}`, "application_role.created", actor.principalId, null, null, { applicationId, roleId, key }, now),
    outboxStatement(database, `application-role:created:outbox:${roleId}`, "application_role.created", "application", applicationId, { applicationId, roleId, key }, now),
  ]);
  return { id: roleId, applicationId, key, name, description, status: "active" as const, grantCount: 0, createdAt: now, updatedAt: now } satisfies ApplicationRole;
