export async function updateApplicationRole(
  environment: AuthEnvironment,
  actor: Actor,
  applicationId: string,
  roleKey: string,
  body: ApplicationRoleUpdateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "application-role-update", 120, 60);
  if (body.name === undefined && body.description === undefined && body.status === undefined) throw new ApiError(400);
  const database = createDb(environment.DB);
  const current = await database.select().from(applicationRoles).where(and(eq(applicationRoles.applicationId, applicationId), eq(applicationRoles.key, normalizeRoleKey(roleKey)))).get();
  if (!current) throw new ApiError(404);
  const name = body.name === undefined ? current.name : normalizeName(body.name);
  const description = body.description === undefined ? current.description : normalizeDescription(body.description);
  const status = body.status ?? current.status;
  const now = Date.now();
  const changed = database.update(applicationRoles).set({ name, description, status, updatedAt: now }).where(eq(applicationRoles.id, current.id)).returning({ id: applicationRoles.id });
  const version = database.select({ value: applicationRoles.id }).from(applicationRoles).where(and(eq(applicationRoles.id, current.id), eq(applicationRoles.updatedAt, now)));
  const result = await database.batch([
    changed,
    applicationAuthzVersionStatement(database, applicationId, now),
    auditStatementWhen(database, `application-role:updated:${current.id}:${now}`, "application_role.updated", actor.principalId, null, null, { applicationId, roleId: current.id, key: current.key, name, description, status }, now, version),
    outboxStatementWhen(database, `application-role:updated:outbox:${current.id}:${now}`, "application_role.updated", "application", applicationId, { applicationId, roleId: current.id, key: current.key, status }, now, version),
  ]);
  if (!result[0]?.length) throw new ApiError(409);
  const updated = await database.select().from(applicationRoles).where(eq(applicationRoles.id, current.id)).get();
  if (!updated) throw new ApiError(404);
  const [userGrants, serviceGrants, teamGrants] = await Promise.all([
    database.select({ id: userApplicationRoleGrants.id }).from(userApplicationRoleGrants).where(eq(userApplicationRoleGrants.roleId, current.id)).all(),
    database.select({ id: serviceAccountApplicationRoleGrants.id }).from(serviceAccountApplicationRoleGrants).where(eq(serviceAccountApplicationRoleGrants.roleId, current.id)).all(),
    database.select({ id: teamApplicationRoleGrants.id }).from(teamApplicationRoleGrants).where(eq(teamApplicationRoleGrants.roleId, current.id)).all(),
  ]);
  return { id: updated.id, applicationId, key: updated.key, name: updated.name, description: updated.description, status: updated.status, grantCount: userGrants.length + serviceGrants.length + teamGrants.length, createdAt: updated.createdAt, updatedAt: updated.updatedAt } satisfies ApplicationRole;
}

