  if (!current) throw new ApiError(404);
  const [userGrants, serviceGrants, teamGrants] = await Promise.all([
    database.select({ id: userApplicationRoleGrants.id }).from(userApplicationRoleGrants).where(eq(userApplicationRoleGrants.roleId, current.id)).all(),
    database.select({ id: serviceAccountApplicationRoleGrants.id }).from(serviceAccountApplicationRoleGrants).where(eq(serviceAccountApplicationRoleGrants.roleId, current.id)).all(),
    database.select({ id: teamApplicationRoleGrants.id }).from(teamApplicationRoleGrants).where(eq(teamApplicationRoleGrants.roleId, current.id)).all(),
  ]);
  if (userGrants.length || serviceGrants.length || teamGrants.length) throw new ApiError(409);
