}

async function resolveSubject(database: AppDb, subjectType: ApplicationSubjectType, subjectId: string): Promise<ResolvedSubject> {
  if (subjectType === "user") {
    const row = await database
      .select({ principalId: principals.id, userId: humanPrincipals.userId, status: principals.status, name: user.name })
      .from(principals)
      .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
      .innerJoin(user, eq(user.id, humanPrincipals.userId))
      .where(or(eq(principals.id, subjectId), eq(humanPrincipals.userId, subjectId)))
      .get();
    if (!row) throw new ApiError(404);
    return { id: row.userId, principalId: row.principalId, userId: row.userId, type: "user", status: row.status, name: row.name };
  }
  if (subjectType === "service-account") {
    const row = await database
      .select({ principalId: principals.id, status: principals.status, name: serviceAccounts.name })
      .from(serviceAccounts)
      .innerJoin(principals, eq(principals.id, serviceAccounts.principalId))
      .where(eq(serviceAccounts.principalId, subjectId))
      .get();
    if (!row) throw new ApiError(404);
    return { id: row.principalId, principalId: row.principalId, userId: null, type: subjectType, status: row.status, name: row.name };
  }
  const row = await database.select({ id: teams.id, status: teams.status, name: teams.name }).from(teams).where(eq(teams.id, subjectId)).get();
  if (!row) throw new ApiError(404);
  return { id: row.id, principalId: null, userId: null, type: subjectType, status: row.status, name: row.name };
}

function assertActiveSubject(subject: ResolvedSubject) {
  if (subject.status !== "active") throw new ApiError(409);
}

export async function setApplicationAssignment(environment: AuthEnvironment, actor: Actor, applicationId: string, body: ApplicationAssignmentBody, request: Request) {
  await enforceRateLimit(environment, request, "application-assignment-set", 180, 60);
  const database = createDb(environment.DB);
  const application = await readApplicationRow(database, applicationId);
  if (application.status !== "active") throw new ApiError(404);
  const subject = await resolveSubject(database, body.subjectType, body.subjectId);
  assertActiveSubject(subject);
  const status = body.status ?? "active";
  const now = Date.now();
  if (body.subjectType === "user") {
    const current = await database.select().from(userApplicationAssignments).where(and(eq(userApplicationAssignments.applicationId, applicationId), eq(userApplicationAssignments.userPrincipalId, subject.principalId ?? ""))).get();
    if (current?.status === status) return { applicationId, subjectId: subject.principalId ?? "", subjectType: body.subjectType, status } as const;
    const mutation = current
      ? database.update(userApplicationAssignments).set({ status, updatedAt: now }).where(eq(userApplicationAssignments.id, current.id)).returning({ id: userApplicationAssignments.id })
      : database.insert(userApplicationAssignments).values({ id: `user-assignment_${crypto.randomUUID()}`, applicationId, userPrincipalId: subject.principalId ?? "", status, createdAt: now, updatedAt: now }).returning({ id: userApplicationAssignments.id });
    const result = await database.batch([mutation, applicationAuthzVersionStatement(database, applicationId, now), auditStatement(database, `application-assignment:${body.subjectType}:${subject.principalId}:${now}`, "application.assignment_set", actor.principalId, subject.principalId, subject.userId, { applicationId, subjectType: body.subjectType, status }, now), outboxStatement(database, `application-assignment:outbox:${body.subjectType}:${subject.principalId}:${now}`, "application.assignment_set", "application", applicationId, { applicationId, subjectType: body.subjectType, subjectId: subject.principalId, status }, now)]);
    if (!result[0]?.length) throw new ApiError(409);
    return { applicationId, subjectId: subject.principalId ?? "", subjectType: body.subjectType, status } as const;
  }
  if (body.subjectType === "service-account") {
    const current = await database.select().from(serviceAccountApplicationAssignments).where(and(eq(serviceAccountApplicationAssignments.applicationId, applicationId), eq(serviceAccountApplicationAssignments.serviceAccountPrincipalId, subject.id))).get();
    if (current?.status === status) return { applicationId, subjectId: subject.id, subjectType: body.subjectType, status } as const;
