      : database.insert(serviceAccountApplicationAssignments).values({ id: `service-assignment_${crypto.randomUUID()}`, applicationId, serviceAccountPrincipalId: subject.id, status, createdAt: now, updatedAt: now }).returning({ id: serviceAccountApplicationAssignments.id });
    const result = await database.batch([mutation, applicationAuthzVersionStatement(database, applicationId, now), auditStatement(database, `application-assignment:${body.subjectType}:${subject.id}:${now}`, "application.assignment_set", actor.principalId, subject.principalId, null, { applicationId, subjectType: body.subjectType, status }, now), outboxStatement(database, `application-assignment:outbox:${body.subjectType}:${subject.id}:${now}`, "application.assignment_set", "application", applicationId, { applicationId, subjectType: body.subjectType, subjectId: subject.id, status }, now)]);
    if (!result[0]?.length) throw new ApiError(409);
    return { applicationId, subjectId: subject.id, subjectType: body.subjectType, status } as const;
  }
  const current = await database.select().from(teamApplicationAssignments).where(and(eq(teamApplicationAssignments.applicationId, applicationId), eq(teamApplicationAssignments.teamId, subject.id))).get();
  if (current?.status === status) return { applicationId, subjectId: subject.id, subjectType: body.subjectType, status } as const;
  const mutation = current
    ? database.update(teamApplicationAssignments).set({ status, updatedAt: now }).where(eq(teamApplicationAssignments.id, current.id)).returning({ id: teamApplicationAssignments.id })
    : database.insert(teamApplicationAssignments).values({ id: `team-assignment_${crypto.randomUUID()}`, applicationId, teamId: subject.id, status, createdAt: now, updatedAt: now }).returning({ id: teamApplicationAssignments.id });
  const result = await database.batch([mutation, applicationAuthzVersionStatement(database, applicationId, now), auditStatement(database, `application-assignment:${body.subjectType}:${subject.id}:${now}`, "application.assignment_set", actor.principalId, null, null, { applicationId, subjectType: body.subjectType, status }, now), outboxStatement(database, `application-assignment:outbox:${body.subjectType}:${subject.id}:${now}`, "application.assignment_set", "application", applicationId, { applicationId, subjectType: body.subjectType, subjectId: subject.id, status }, now)]);
  if (!result[0]?.length) throw new ApiError(409);
  return { applicationId, subjectId: subject.id, subjectType: body.subjectType, status } as const;
}

