export async function revokeApplicationRole(environment: AuthEnvironment, actor: Actor, applicationId: string, subjectType: ApplicationSubjectType, subjectId: string, roleKey: string, request: Request) {
  await enforceRateLimit(environment, request, "application-role-revoke", 180, 60);
  const database = createDb(environment.DB);
  await readApplicationRow(database, applicationId);
  const subject = await resolveSubject(database, subjectType, subjectId);
  const role = await database.select({ id: applicationRoles.id, key: applicationRoles.key }).from(applicationRoles).where(and(eq(applicationRoles.applicationId, applicationId), eq(applicationRoles.key, normalizeRoleKey(roleKey)))).get();
  if (!role) throw new ApiError(404);
  const key = subject.principalId ?? subject.id;
  let mutation;
  if (subjectType === "user") {
    mutation = database.delete(userApplicationRoleGrants).where(and(eq(userApplicationRoleGrants.applicationId, applicationId), eq(userApplicationRoleGrants.userPrincipalId, key), eq(userApplicationRoleGrants.roleId, role.id))).returning({ id: userApplicationRoleGrants.id });
  } else if (subjectType === "service-account") {
    mutation = database.delete(serviceAccountApplicationRoleGrants).where(and(eq(serviceAccountApplicationRoleGrants.applicationId, applicationId), eq(serviceAccountApplicationRoleGrants.serviceAccountPrincipalId, key), eq(serviceAccountApplicationRoleGrants.roleId, role.id))).returning({ id: serviceAccountApplicationRoleGrants.id });
  } else {
    mutation = database.delete(teamApplicationRoleGrants).where(and(eq(teamApplicationRoleGrants.applicationId, applicationId), eq(teamApplicationRoleGrants.teamId, key), eq(teamApplicationRoleGrants.roleId, role.id))).returning({ id: teamApplicationRoleGrants.id });
  }
  const now = Date.now();
  const result = await database.batch([mutation, applicationAuthzVersionStatement(database, applicationId, now), auditStatement(database, `application-role:revoked:${subjectType}:${key}:${role.id}:${now}`, "application_role.revoked", actor.principalId, subject.principalId, subject.userId, { applicationId, subjectType, subjectId: key, roleKey: role.key }, now), outboxStatement(database, `application-role:revoked:outbox:${subjectType}:${key}:${role.id}:${now}`, "application_role.revoked", "application", applicationId, { applicationId, subjectType, subjectId: key, roleKey: role.key }, now)]);
  if (!result[0]?.length) return { applicationId, subjectId: key, subjectType, roleKey: role.key, status: "revoked" as const };
  return { applicationId, subjectId: key, subjectType, roleKey: role.key, status: "revoked" as const };
}

export async function readApplicationAccess(environment: AuthEnvironment, applicationId: string): Promise<ApplicationAccess> {
  const database = createDb(environment.DB);
  await readApplicationRow(database, applicationId);
  const [users, serviceRows, teamRows, userAssignments, serviceAssignments, teamAssignments, userGrants, serviceGrants, teamGrants, memberships] = await Promise.all([
    database.select({ id: user.id, principalId: humanPrincipals.principalId, name: user.name, email: user.email, status: principals.status, humanStatus: humanPrincipals.status, disabled: humanPrincipals.disabled }).from(user).innerJoin(humanPrincipals, eq(humanPrincipals.userId, user.id)).innerJoin(principals, eq(principals.id, humanPrincipals.principalId)).orderBy(asc(user.name)).all(),
    database.select({ principalId: serviceAccounts.principalId, name: serviceAccounts.name, status: principals.status }).from(serviceAccounts).innerJoin(principals, eq(principals.id, serviceAccounts.principalId)).orderBy(asc(serviceAccounts.name)).all(),
    database.select({ id: teams.id, name: teams.name, status: teams.status }).from(teams).orderBy(asc(teams.name)).all(),
    database.select().from(userApplicationAssignments).where(eq(userApplicationAssignments.applicationId, applicationId)).all(),
    database.select().from(serviceAccountApplicationAssignments).where(eq(serviceAccountApplicationAssignments.applicationId, applicationId)).all(),
    database.select().from(teamApplicationAssignments).where(eq(teamApplicationAssignments.applicationId, applicationId)).all(),
    database.select({ principalId: userApplicationRoleGrants.userPrincipalId, key: applicationRoles.key }).from(userApplicationRoleGrants).innerJoin(applicationRoles, eq(applicationRoles.id, userApplicationRoleGrants.roleId)).where(and(eq(userApplicationRoleGrants.applicationId, applicationId), eq(applicationRoles.status, "active"))).all(),
    database.select({ principalId: serviceAccountApplicationRoleGrants.serviceAccountPrincipalId, key: applicationRoles.key }).from(serviceAccountApplicationRoleGrants).innerJoin(applicationRoles, eq(applicationRoles.id, serviceAccountApplicationRoleGrants.roleId)).where(and(eq(serviceAccountApplicationRoleGrants.applicationId, applicationId), eq(applicationRoles.status, "active"))).all(),
    database.select({ teamId: teamApplicationRoleGrants.teamId, key: applicationRoles.key }).from(teamApplicationRoleGrants).innerJoin(applicationRoles, eq(applicationRoles.id, teamApplicationRoleGrants.roleId)).where(and(eq(teamApplicationRoleGrants.applicationId, applicationId), eq(applicationRoles.status, "active"))).all(),
    database.select({ teamId: teamMemberships.teamId, principalId: teamMemberships.userPrincipalId, teamName: teams.name, teamStatus: teams.status }).from(teamMemberships).innerJoin(teams, eq(teams.id, teamMemberships.teamId)).all(),
  ]);
  const userAssignmentMap = new Map(userAssignments.map((row) => [row.userPrincipalId, row.status]));
  const serviceAssignmentMap = new Map(serviceAssignments.map((row) => [row.serviceAccountPrincipalId, row.status]));
  const teamAssignmentMap = new Map(teamAssignments.map((row) => [row.teamId, row.status]));
  const directUserRoles = new Map<string, string[]>();
  for (const row of userGrants) directUserRoles.set(row.principalId, [...(directUserRoles.get(row.principalId) ?? []), row.key]);
  const directServiceRoles = new Map<string, string[]>();
  for (const row of serviceGrants) directServiceRoles.set(row.principalId, [...(directServiceRoles.get(row.principalId) ?? []), row.key]);
  const teamRoleMap = new Map<string, string[]>();
  for (const row of teamGrants) teamRoleMap.set(row.teamId, [...(teamRoleMap.get(row.teamId) ?? []), row.key]);
  const membershipsByPrincipal = new Map<string, typeof memberships>();
  for (const membership of memberships) membershipsByPrincipal.set(membership.principalId, [...(membershipsByPrincipal.get(membership.principalId) ?? []), membership]);

  const userAccess = users.map((row) => {
    const directRoles = Array.from(new Set(directUserRoles.get(row.principalId) ?? []));
    const teamRoles = (membershipsByPrincipal.get(row.principalId) ?? [])
      .filter((membership) => membership.teamStatus === "active")
      .flatMap((membership) => (teamRoleMap.get(membership.teamId) ?? []).map((roleKey) => ({ kind: "team" as const, roleKey, teamId: membership.teamId, teamName: membership.teamName })));
    const teamAccess = (membershipsByPrincipal.get(row.principalId) ?? []).some((membership) => membership.teamStatus === "active" && teamAssignmentMap.get(membership.teamId) === "active");
    const principalActive = row.status === "active" && row.humanStatus === "active" && !row.disabled;
    const effectiveRoles = principalActive && (userAssignmentMap.get(row.principalId) === "active" || teamAccess)
      ? Array.from(new Set([...directRoles, ...teamRoles.map((origin) => origin.roleKey)]))
      : [];
    return { id: row.id, principalId: row.principalId, name: row.name, email: row.email, status: principalActive ? "active" as const : "disabled" as const, assignmentStatus: userAssignmentMap.get(row.principalId) ?? null, directRoles, teamRoles, effectiveRoles };
  });
  const serviceAccountsAccess = serviceRows.map((row) => {
    const directRoles = Array.from(new Set(directServiceRoles.get(row.principalId) ?? []));
    return { id: row.principalId, principalId: row.principalId, name: row.name, status: row.status, assignmentStatus: serviceAssignmentMap.get(row.principalId) ?? null, directRoles, effectiveRoles: row.status === "active" && serviceAssignmentMap.get(row.principalId) === "active" ? directRoles : [] };
  });
  const teamsAccess = teamRows.map((row) => ({ id: row.id, name: row.name, status: row.status, assignmentStatus: teamAssignmentMap.get(row.id) ?? null, directRoles: Array.from(new Set(teamRoleMap.get(row.id) ?? [])) }));
  return { applicationId, users: userAccess, serviceAccounts: serviceAccountsAccess, teams: teamsAccess };
}

async function readApplicationClient(database: AppDb, applicationId: string, clientId: string) {
  const row = await database
    .select({
      applicationId: applicationOauthClients.applicationId,
      clientId: oauthClient.clientId,
      clientType: applicationOauthClients.clientType,
