export async function updateApplicationClient(environment: AuthEnvironment, actor: Actor, applicationId: string, clientId: string, body: ApplicationClientUpdateBody, request: Request) {
  await enforceRateLimit(environment, request, "application-client-update", 60, 60);
  if (body.name === undefined && body.redirectUris === undefined && body.scopes === undefined) throw new ApiError(400);
  const database = createDb(environment.DB);
  const current = await readApplicationClient(database, applicationId, clientId);
  const name = body.name === undefined ? current.name : normalizeName(body.name);
  const redirectUris = body.redirectUris === undefined ? current.redirectUris : normalizeRedirectUris(body.redirectUris);
  const scopes = body.scopes === undefined ? current.scopes : normalizeScopes(body.scopes);
  const now = Date.now();
  const changed = database.update(oauthClient).set({ name, redirectUris, scopes, updatedAt: new Date(now) }).where(eq(oauthClient.clientId, clientId)).returning({ clientId: oauthClient.clientId });
  const updated = database.select({ value: oauthClient.clientId }).from(oauthClient).where(and(eq(oauthClient.clientId, clientId), eq(oauthClient.updatedAt, new Date(now))));
  const result = await database.batch([changed, applicationAuthzVersionStatement(database, applicationId, now), auditStatementWhen(database, `application-client:updated:${clientId}:${now}`, "application_oauth_client.updated", actor.principalId, null, null, { applicationId, clientId }, now, updated), outboxStatementWhen(database, `application-client:updated:outbox:${clientId}:${now}`, "application_oauth_client.updated", "application", applicationId, { applicationId, clientId }, now, updated)]);
