  return readApplicationClient(database, applicationId, clientId);
}

export async function setApplicationClientDisabled(environment: AuthEnvironment, actor: Actor, applicationId: string, clientId: string, disabled: boolean, request: Request) {
  await enforceRateLimit(environment, request, disabled ? "application-client-disable" : "application-client-enable", 60, 60);
  const database = createDb(environment.DB);
  const current = await readApplicationClient(database, applicationId, clientId);
  if (current.disabled === disabled) return current;
  const now = Date.now();
  const changed = database.update(oauthClient).set({ disabled, updatedAt: new Date(now) }).where(and(eq(oauthClient.clientId, clientId), eq(oauthClient.disabled, !disabled))).returning({ clientId: oauthClient.clientId });
  const updated = database.select({ value: oauthClient.clientId }).from(oauthClient).where(and(eq(oauthClient.clientId, clientId), eq(oauthClient.disabled, disabled), eq(oauthClient.updatedAt, new Date(now))));
  const result = await database.batch([changed, applicationAuthzVersionStatement(database, applicationId, now), auditStatementWhen(database, `application-client:${disabled ? "disabled" : "enabled"}:${clientId}:${now}`, `application_oauth_client.${disabled ? "disabled" : "enabled"}`, actor.principalId, null, null, { applicationId, clientId, disabled }, now, updated), outboxStatementWhen(database, `application-client:${disabled ? "disabled" : "enabled"}:outbox:${clientId}:${now}`, `application_oauth_client.${disabled ? "disabled" : "enabled"}`, "application", applicationId, { applicationId, clientId, disabled }, now, updated)]);
  if (!result[0]?.length) throw new ApiError(409);
  return readApplicationClient(database, applicationId, clientId);
}

export async function deleteApplicationClient(environment: AuthEnvironment, actor: Actor, applicationId: string, clientId: string, request: Request) {
