  await database.batch([
    database.delete(applicationOauthClients).where(and(eq(applicationOauthClients.applicationId, applicationId), eq(applicationOauthClients.clientId, clientId))),
    database.delete(oauthClient).where(eq(oauthClient.clientId, clientId)),
    applicationAuthzVersionStatement(database, applicationId, now),
    auditStatement(database, `application-client:deleted:${clientId}:${now}`, "application_oauth_client.deleted", actor.principalId, null, null, { applicationId, clientId }, now),
    outboxStatement(database, `application-client:deleted:outbox:${clientId}:${now}`, "application_oauth_client.deleted", "application", applicationId, { applicationId, clientId }, now),
  ]);
  return { clientId, status: "deleted" as const };
}

