import { Badge, Button, Dialog, Grid, Input, LayerCard, Select } from "@cloudflare/kumo";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState, type FormEvent } from "react";

import {
  formatApiError,
  type Application,
  type ApplicationClientCreated,
} from "../lib/api-client";
import {
  apiQueryKeys,
  applicationAccessQueryOptions,
  applicationClientsQueryOptions,
  applicationOwnersQueryOptions,
  applicationRolesQueryOptions,
  applicationsQueryOptions,
  createApplicationClientMutationOptions,
  createApplicationMutationOptions,
  createApplicationRoleMutationOptions,
  deleteApplicationClientMutationOptions,
  deleteApplicationMutationOptions,
  deleteApplicationRoleMutationOptions,
  grantApplicationRoleMutationOptions,
  removeApplicationAssignmentMutationOptions,
  revokeApplicationRoleMutationOptions,
  setApplicationAssignmentMutationOptions,
  setApplicationClientStatusMutationOptions,
  setApplicationStatusMutationOptions,
  transferApplicationOwnershipMutationOptions,
  updateApplicationClientMutationOptions,
  updateApplicationMutationOptions,
  updateApplicationRoleMutationOptions,
} from "../lib/api-query-options";
import {
  AdminConfirmDialog,
  AdminError,
  AdminLayout,
  AdminStatus,
  StatusPill,
} from "./admin-layout";

export function ApplicationsAdminPage() {
  const queryClient = useQueryClient();
  const applicationsQuery = useQuery(applicationsQueryOptions);
  const ownersQuery = useQuery(applicationOwnersQueryOptions);
  const createMutation = useMutation(createApplicationMutationOptions());
  const [selectedId, setSelectedId] = useState<string>();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [resourceIdentifier, setResourceIdentifier] = useState("");
  const [ownerType, setOwnerType] = useState<"user" | "team">("user");
  const [ownerId, setOwnerId] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string>();
  const [status, setStatus] = useState<string>();

  async function refresh(message?: string) {
    await queryClient.invalidateQueries({ queryKey: apiQueryKeys.applications });
    if (message) setStatus(message);
  }

  async function create(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setBusy(true);
    setError(undefined);
    setStatus(undefined);
    try {
      const application = await createMutation.mutateAsync({
        description: description || undefined,
        name,
        ownerId,
        ownerType,
        resourceIdentifier: resourceIdentifier || undefined,
      });
      setName("");
      setDescription("");
      setResourceIdentifier("");
      setOwnerId("");
      setSelectedId(application.id);
      await refresh("Application created.");
    } catch (createError) {
      setError(formatApiError(createError));
    } finally {
      setBusy(false);
    }
  }

  const applications = applicationsQuery.data?.applications ?? [];
  const owners = ownersQuery.data;
  const ownerItems =
    ownerType === "user"
      ? (owners?.users ?? []).map((owner) => ({ label: owner.name, value: owner.id }))
      : (owners?.teams ?? []).map((owner) => ({ label: owner.name, value: owner.id }));

  return (
    <AdminLayout
      activePath="/admin/applications"
      description="Applications define the boundary where assignments, roles, and OIDC clients meet. Access remains explicit: a role grant never creates an assignment."
      eyebrow="Authorization / Applications"
      title="Make every access decision legible."
    >
      <div className="space-y-8">
        <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
          <h2 className="text-xl font-semibold text-kumo-strong">New application</h2>
          <p className="mt-2 max-w-2xl text-sm leading-6 text-kumo-subtle">
            Resource identifiers are immutable. Leave the field empty to generate one from the
            current Shui issuer.
          </p>
          <form className="mt-5 grid gap-4 lg:grid-cols-2" onSubmit={create}>
            <Input
              id="application-name"
              label="Name"
              onChange={(event) => setName(event.target.value)}
              required
              value={name}
            />
            <Input
              id="application-description"
              label="Description (optional)"
              onChange={(event) => setDescription(event.target.value)}
              value={description}
            />
            <Input
              id="application-resource"
              label="Resource identifier (optional)"
              onChange={(event) => setResourceIdentifier(event.target.value)}
              type="url"
              value={resourceIdentifier}
            />
            <Select
              items={[
                { label: "User", value: "user" },
                { label: "Team", value: "team" },
              ]}
              label="Owner type"
              onValueChange={(value) => {
                const nextType = value === "team" ? "team" : "user";
                setOwnerType(nextType);
                setOwnerId("");
              }}
              value={ownerType}
            />
            <Select
              items={ownerItems}
              label="Owner"
              onValueChange={(value) => setOwnerId(value ?? "")}
              placeholder="Choose an owner"
              required
              value={ownerId || null}
            />
            <div className="lg:col-span-2">
              <Button aria-busy={busy} disabled={busy || !ownerId} type="submit" variant="primary">
                Create application
              </Button>
            </div>
          </form>
        </LayerCard>

        {applicationsQuery.isLoading || ownersQuery.isLoading ? (
          <AdminStatus>Loading applications...</AdminStatus>
        ) : null}
        {applicationsQuery.isError ? (
          <AdminError>{formatApiError(applicationsQuery.error)}</AdminError>
        ) : null}
        {ownersQuery.isError ? <AdminError>{formatApiError(ownersQuery.error)}</AdminError> : null}
        {error ? <AdminError>{error}</AdminError> : null}
        {status ? <AdminStatus>{status}</AdminStatus> : null}

        <Grid gap="sm" variant="2up">
          {applications.map((application) => (
            <ApplicationCard
              application={application}
              key={application.id}
              onSelect={() => setSelectedId(application.id)}
              selected={selectedId === application.id}
            />
          ))}
        </Grid>
        {!applicationsQuery.isLoading && applications.length === 0 ? (
          <LayerCard className="bg-kumo-elevated p-6 ring ring-kumo-line">
            <h2 className="text-lg font-semibold text-kumo-strong">No applications yet</h2>
            <p className="mt-2 text-sm leading-6 text-kumo-subtle">
              Create the first application to start assigning people and teams.
            </p>
          </LayerCard>
        ) : null}

        {selectedId ? (
          <ApplicationDetail
            application={applications.find((application) => application.id === selectedId)}
            owners={owners}
            onRefresh={refresh}
          />
        ) : null}
      </div>
    </AdminLayout>
  );
}

function ApplicationCard({
  application,
  onSelect,
  selected,
}: Readonly<{
  application: Application;
  onSelect: () => void;
  selected: boolean;
}>) {
  return (
    <LayerCard
      className={`bg-kumo-elevated p-5 ring sm:p-6 ${selected ? "ring-(--tangerine)" : "ring-kumo-line"}`}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <h2 className="truncate text-xl font-semibold text-kumo-strong">{application.name}</h2>
          <p className="mt-1 text-sm text-kumo-subtle">
            {application.description || "No description"}
          </p>
        </div>
        <StatusPill status={application.status} />
      </div>
      <dl className="mt-5 grid gap-3 border-t border-kumo-hairline pt-5 text-sm sm:grid-cols-3">
        <div>
          <dt className="text-kumo-subtle">Owner</dt>
          <dd className="mt-1 truncate font-medium text-kumo-strong">{application.owner.label}</dd>
        </div>
        <div>
          <dt className="text-kumo-subtle">Roles</dt>
          <dd className="mt-1 font-medium text-kumo-strong">{application.roleCount}</dd>
        </div>
        <div>
          <dt className="text-kumo-subtle">Assignments</dt>
          <dd className="mt-1 font-medium text-kumo-strong">{application.assignmentCount}</dd>
        </div>
      </dl>
      <Button className="mt-5" onClick={onSelect} type="button" variant={selected ? "secondary" : "ghost"}>
        {selected ? "Application selected" : "Manage application"}
      </Button>
    </LayerCard>
  );
}

function ApplicationDetail({
  application,
  onRefresh,
  owners,
}: Readonly<{
  application: Application | undefined;
  onRefresh: (message?: string) => Promise<void>;
  owners:
    | {
        teams: Array<{ id: string; name: string }>;
        users: Array<{ id: string; name: string }>;
      }
    | undefined;
}>) {
  if (!application) {
    return <AdminError>The selected application is no longer available.</AdminError>;
  }

  return (
    <section aria-labelledby="application-detail-title" className="space-y-6">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-sm font-medium uppercase tracking-[0.16em] text-(--tangerine)">
            Application detail
          </p>
          <h2 className="mt-2 font-display text-3xl font-semibold text-kumo-strong" id="application-detail-title">
            {application.name}
          </h2>
        </div>
        <Badge appearance="outline" variant="neutral">
          authz version {application.authzVersion}
        </Badge>
      </div>
      <ApplicationSettings application={application} onRefresh={onRefresh} owners={owners} />
      <Grid gap="sm" variant="2up">
        <ApplicationRoles applicationId={application.id} onRefresh={onRefresh} />
        <ApplicationClients applicationId={application.id} onRefresh={onRefresh} />
      </Grid>
      <ApplicationAccess applicationId={application.id} onRefresh={onRefresh} />
    </section>
  );
}

function ApplicationSettings({
  application,
  onRefresh,
  owners,
}: Readonly<{
  application: Application;
  onRefresh: (message?: string) => Promise<void>;
  owners:
    | {
        teams: Array<{ id: string; name: string }>;
        users: Array<{ id: string; name: string }>;
      }
    | undefined;
}>) {
  const queryClient = useQueryClient();
  const updateMutation = useMutation(updateApplicationMutationOptions());
  const transferMutation = useMutation(transferApplicationOwnershipMutationOptions());
  const statusMutation = useMutation(setApplicationStatusMutationOptions());
  const deleteMutation = useMutation(deleteApplicationMutationOptions());
  const [name, setName] = useState(application.name);
  const [description, setDescription] = useState(application.description ?? "");
  const [ownerType, setOwnerType] = useState<"user" | "team">(application.owner.type);
  const [ownerId, setOwnerId] = useState(application.owner.id);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string>();

  const ownerItems =
    ownerType === "user"
      ? (owners?.users ?? []).map((owner) => ({ label: owner.name, value: owner.id }))
      : (owners?.teams ?? []).map((owner) => ({ label: owner.name, value: owner.id }));

  async function run(action: () => Promise<unknown>, message: string) {
    setBusy(true);
    setError(undefined);
    try {
      await action();
      await queryClient.invalidateQueries({ queryKey: apiQueryKeys.applications });
      await onRefresh(message);
    } catch (actionError) {
      setError(formatApiError(actionError));
    } finally {
      setBusy(false);
    }
  }

  return (
    <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h3 className="text-xl font-semibold text-kumo-strong">Application settings</h3>
          <p className="mt-2 max-w-3xl break-all font-mono text-xs leading-5 text-kumo-subtle">
            Resource: {application.resourceIdentifier}
          </p>
        </div>
        <StatusPill status={application.status} />
      </div>
      <form
        className="mt-5 grid gap-4 border-t border-kumo-hairline pt-5 md:grid-cols-2"
        onSubmit={(event) => {
          event.preventDefault();
          void run(
            () => updateMutation.mutateAsync({ body: { description: description || null, name }, id: application.id }),
            "Application updated.",
          );
        }}
      >
        <Input id={`application-name-${application.id}`} label="Name" onChange={(event) => setName(event.target.value)} value={name} />
        <Input id={`application-description-${application.id}`} label="Description" onChange={(event) => setDescription(event.target.value)} value={description} />
        <div className="flex flex-wrap gap-3 md:col-span-2">
          <Button disabled={busy} type="submit" variant="primary">Save details</Button>
          <Button
            disabled={busy}
            onClick={() => void run(() => statusMutation.mutateAsync({ id: application.id, status: application.status === "active" ? "disabled" : "active" }), application.status === "active" ? "Application disabled." : "Application enabled.")}
            type="button"
            variant="ghost"
          >
            {application.status === "active" ? "Disable" : "Enable"}
          </Button>
          <AdminConfirmDialog
            confirmLabel="Delete application"
            description="The application can only be deleted when it has no Clients, Roles, Grants, or Assignments. This action cannot be undone."
            onConfirm={() => void run(() => deleteMutation.mutateAsync(application.id), "Application deleted.")}
            title={`Delete ${application.name}?`}
            trigger={<Button disabled={busy} type="button" variant="secondary-destructive">Delete</Button>}
          />
        </div>
      </form>
      <div className="mt-5 border-t border-kumo-hairline pt-5">
        <p className="text-sm text-kumo-subtle">
          Current owner: <span className="font-medium text-kumo-strong">{application.owner.label}</span>{" "}
          ({application.owner.type})
        </p>
        <form
          className="mt-4 grid gap-3 md:grid-cols-[12rem_minmax(0,1fr)_auto] md:items-end"
          onSubmit={(event) => {
            event.preventDefault();
            if (!ownerId) return;
            void run(
              () => transferMutation.mutateAsync({ body: { ownerId, ownerType }, id: application.id }),
              "Application ownership transferred.",
            );
          }}
        >
          <Select
            items={[
              { label: "User", value: "user" },
              { label: "Team", value: "team" },
            ]}
            label="Transfer type"
            onValueChange={(value) => {
              const nextType = value === "team" ? "team" : "user";
              setOwnerType(nextType);
              setOwnerId("");
            }}
            value={ownerType}
          />
          <Select items={ownerItems} label="New owner" onValueChange={(value) => setOwnerId(value ?? "")} placeholder="Choose an owner" required value={ownerId || null} />
          <Button disabled={busy || !ownerId} type="submit" variant="secondary">Transfer ownership</Button>
        </form>
      </div>
      {error ? <AdminError>{error}</AdminError> : null}
    </LayerCard>
  );
}

