import { and, asc, eq } from "drizzle-orm";

import { user } from "../../../db/auth-schema";
import { createDb } from "../../../db";
import { humanPrincipals, principals, serviceAccounts, teams } from "../../../db/domain-schema";
import { type AuthEnvironment } from "../../auth";
import { applicationsForPrincipalAuthzVersionStatement } from "../applications/service";
import { type Actor } from "../authorization/service";
import { ApiError } from "../errors";
import { resolveActiveOwner, type OwnershipInput } from "../ownership";
import {
  auditStatement,
  auditStatementWhen,
  enforceRateLimit,
  outboxStatement,
  outboxStatementWhen,
} from "../../shared/infrastructure";

type ServiceAccountCreateBody = OwnershipInput & {
  description?: string;
  name: string;
};

type ServiceAccountUpdateBody = {
  description?: string | null;
  name?: string;
  ownerId?: string;
  ownerType?: "user" | "team";
};

function normalizeServiceAccountName(name: string) {
  const normalized = name.normalize("NFKC").trim();
  if (!normalized || normalized.length > 160) throw new ApiError(400);
  return normalized;
}

function normalizeDescription(description: string | null | undefined) {
  if (description === undefined || description === null) return description ?? null;
  const normalized = description.normalize("NFKC").trim();
  if (normalized.length > 1000) throw new ApiError(400);
  return normalized || null;
}

export async function listServiceAccounts(environment: AuthEnvironment) {
  const db = createDb(environment.DB);
  const rows = await db
    .select({
      principalId: serviceAccounts.principalId,
      status: principals.status,
      name: serviceAccounts.name,
      description: serviceAccounts.description,
      ownerUserPrincipalId: serviceAccounts.ownerUserPrincipalId,
      ownerTeamId: serviceAccounts.ownerTeamId,
      createdAt: serviceAccounts.createdAt,
      updatedAt: serviceAccounts.updatedAt,
    })
    .from(serviceAccounts)
    .innerJoin(principals, eq(principals.id, serviceAccounts.principalId))
    .orderBy(asc(serviceAccounts.name))
    .all();
  const userOwners = await db
    .select({ principalId: principals.id, name: user.name, email: user.email })
    .from(principals)
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .innerJoin(user, eq(user.id, humanPrincipals.userId))
    .all();
  const teamOwners = await db.select({ id: teams.id, name: teams.name }).from(teams).all();
  const userOwnerMap = new Map(userOwners.map((owner) => [owner.principalId, owner]));
  const teamOwnerMap = new Map(teamOwners.map((owner) => [owner.id, owner]));

  return rows.map((row) => ({
    id: row.principalId,
    principalId: row.principalId,
    name: row.name,
    description: row.description,
    status: row.status,
    owner: row.ownerUserPrincipalId
      ? {
          id: row.ownerUserPrincipalId,
          label: userOwnerMap.get(row.ownerUserPrincipalId)?.name ?? row.ownerUserPrincipalId,
          type: "user" as const,
        }
      : {
          id: row.ownerTeamId ?? "",
          label: teamOwnerMap.get(row.ownerTeamId ?? "")?.name ?? row.ownerTeamId ?? "",
          type: "team" as const,
        },
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  }));
}

export async function listServiceAccountOwners(environment: AuthEnvironment) {
  const db = createDb(environment.DB);
  const users = await db
    .select({ id: humanPrincipals.principalId, name: user.name })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .innerJoin(user, eq(user.id, humanPrincipals.userId))
    .where(
      and(
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
      ),
    )
    .orderBy(asc(user.name))
    .all();
  const teamRows = await db
    .select({ id: teams.id, name: teams.name })
    .from(teams)
    .where(eq(teams.status, "active"))
    .orderBy(asc(teams.name))
    .all();

  return { teams: teamRows, users };
}

export async function createServiceAccount(
  environment: AuthEnvironment,
  actor: Actor,
  body: ServiceAccountCreateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "service-account-create", 60, 60);
  const db = createDb(environment.DB);
  const name = normalizeServiceAccountName(body.name);
  const description = normalizeDescription(body.description);
  const ownership = await resolveActiveOwner(db, body);
  const principalId = `service_${crypto.randomUUID()}`;
  const now = Date.now();

  await db.batch([
    db.insert(principals).values({
      id: principalId,
      type: "service",
      status: "active",
      disabledAt: null,
      createdAt: now,
      updatedAt: now,
    }),
    db.insert(serviceAccounts).values({
      principalId,
      name,
      description,
      ownerUserPrincipalId: ownership.ownerUserPrincipalId,
      ownerTeamId: ownership.ownerTeamId,
      createdAt: now,
      updatedAt: now,
    }),
    auditStatement(
      db,
      `service-account:created:${principalId}`,
      "service_account.created",
      actor.principalId,
      principalId,
      null,
      { name, owner: ownership.owner },
      now,
    ),
    outboxStatement(
      db,
      `service-account:created:outbox:${principalId}`,
      "service_account.created",
      "principal",
      principalId,
      { name, owner: ownership.owner },
      now,
    ),
  ]);

  return {
    id: principalId,
    principalId,
    name,
    description,
    status: "active" as const,
    owner: ownership.owner,
    createdAt: now,
    updatedAt: now,
  };
}

export async function updateServiceAccount(
  environment: AuthEnvironment,
  actor: Actor,
  principalId: string,
  body: ServiceAccountUpdateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "service-account-update", 60, 60);
  if (body.name === undefined && body.description === undefined && body.ownerId === undefined) {
    throw new ApiError(400);
  }
  if ((body.ownerId === undefined) !== (body.ownerType === undefined)) throw new ApiError(400);

  const db = createDb(environment.DB);
  const current = await db
    .select({
      principalId: serviceAccounts.principalId,
      status: principals.status,
      name: serviceAccounts.name,
      description: serviceAccounts.description,
      ownerUserPrincipalId: serviceAccounts.ownerUserPrincipalId,
      ownerTeamId: serviceAccounts.ownerTeamId,
      createdAt: serviceAccounts.createdAt,
      updatedAt: serviceAccounts.updatedAt,
    })
    .from(serviceAccounts)
    .innerJoin(principals, eq(principals.id, serviceAccounts.principalId))
    .where(and(eq(serviceAccounts.principalId, principalId), eq(principals.type, "service")))
    .get();
  if (!current) throw new ApiError(404);
  const name = body.name === undefined ? current.name : normalizeServiceAccountName(body.name);
  const description =
    body.description === undefined ? current.description : normalizeDescription(body.description);
  const ownership =
    body.ownerId === undefined
      ? {
          ownerUserPrincipalId: current.ownerUserPrincipalId,
          ownerTeamId: current.ownerTeamId,
          owner: await readOwner(db, current.ownerUserPrincipalId, current.ownerTeamId),
        }
      : await resolveActiveOwner(db, {
          ownerId: body.ownerId,
          ownerType: body.ownerType ?? "user",
        });
  const now = Date.now();
  const changed = db
    .update(serviceAccounts)
    .set({
      name,
      description,
      ownerUserPrincipalId: ownership.ownerUserPrincipalId,
      ownerTeamId: ownership.ownerTeamId,
      updatedAt: now,
    })
    .where(eq(serviceAccounts.principalId, principalId))
    .returning({ id: serviceAccounts.principalId });
  const updated = db
    .select({ value: serviceAccounts.principalId })
    .from(serviceAccounts)
    .where(and(eq(serviceAccounts.principalId, principalId), eq(serviceAccounts.updatedAt, now)));
  const result = await db.batch([
    changed,
    auditStatementWhen(
      db,
      `service-account:updated:${principalId}:${now}`,
      "service_account.updated",
      actor.principalId,
      principalId,
      null,
      { name, description, owner: ownership.owner },
      now,
      updated,
    ),
    outboxStatementWhen(
      db,
      `service-account:updated:outbox:${principalId}:${now}`,
    mutation,
    applicationAuthzVersionStatement(database, applicationId, now),
    auditStatement(
      database,
      `application-assignment:${body.subjectType}:${subject.id}:${now}`,
      "application.assignment_set",
      actor.principalId,
      null,
      null,
      { applicationId, subjectType: body.subjectType, status },
      now,
    ),
    outboxStatement(
      database,
      `application-assignment:outbox:${body.subjectType}:${subject.id}:${now}`,
      "application.assignment_set",
      "application",
      applicationId,
      { applicationId, subjectType: body.subjectType, subjectId: subject.id, status },
      now,
    ),
  ]);
  if (!result[0]?.length) throw new ApiError(409);
  return { applicationId, subjectId: subject.id, subjectType: body.subjectType, status } as const;
}

export async function removeApplicationAssignment(
  environment: AuthEnvironment,
  actor: Actor,
  applicationId: string,
  subjectType: ApplicationSubjectType,
  subjectId: string,
  request: Request,
) {
  await enforceRateLimit(environment, request, "application-assignment-remove", 180, 60);
  const database = createDb(environment.DB);
  await readApplicationRow(database, applicationId);
  const subject = await resolveSubject(database, subjectType, subjectId);
  const now = Date.now();
  let mutation;
  if (subjectType === "user") {
    mutation = database
      .delete(userApplicationAssignments)
      .where(
        and(
          eq(userApplicationAssignments.applicationId, applicationId),
          eq(userApplicationAssignments.userPrincipalId, subject.principalId ?? ""),
        ),
      )
      .returning({ id: userApplicationAssignments.id });
  } else if (subjectType === "service-account") {
    mutation = database
      .delete(serviceAccountApplicationAssignments)
      .where(
        and(
          eq(serviceAccountApplicationAssignments.applicationId, applicationId),
          eq(serviceAccountApplicationAssignments.serviceAccountPrincipalId, subject.id),
        ),
      )
      .returning({ id: serviceAccountApplicationAssignments.id });
  } else {
    mutation = database
      .delete(teamApplicationAssignments)
      .where(
        and(
          eq(teamApplicationAssignments.applicationId, applicationId),
          eq(teamApplicationAssignments.teamId, subject.id),
        ),
      )
      .returning({ id: teamApplicationAssignments.id });
  }
  const result = await database.batch([
    mutation,
    applicationAuthzVersionStatement(database, applicationId, now),
    auditStatement(
      database,
      `application-assignment:removed:${subjectType}:${subject.id}:${now}`,
      "application.assignment_removed",
      actor.principalId,
      subject.principalId,
      subject.userId,
      { applicationId, subjectType, subjectId: subject.id },
      now,
    ),
    outboxStatement(
      database,
      `application-assignment:removed:outbox:${subjectType}:${subject.id}:${now}`,
      "application.assignment_removed",
      "application",
      applicationId,
      { applicationId, subjectType, subjectId: subject.id },
      now,
    ),
  ]);
  if (!result[0]?.length) throw new ApiError(404);
  return {
    applicationId,
    subjectId: subject.principalId ?? subject.id,
    subjectType,
    status: "removed" as const,
  };
}

