 48	  const [ownerId, setOwnerId] = useState("");
 49	  const [busy, setBusy] = useState(false);
 50	  const [error, setError] = useState<string>();
 51	  const [status, setStatus] = useState<string>();
 52	
 53	  async function refresh(message?: string) {
 54	    await queryClient.invalidateQueries({ queryKey: apiQueryKeys.applications });
 55	    if (message) setStatus(message);
 56	  }
 57	
 58	  async function create(event: FormEvent<HTMLFormElement>) {
 59	    event.preventDefault();
 60	    setBusy(true);
 61	    setError(undefined);
 62	    setStatus(undefined);
 63	    try {
 64	      const application = await createMutation.mutateAsync({
 65	        description: description || undefined,
 66	        name,
 67	        ownerId,
 68	        ownerType,
 69	        resourceIdentifier: resourceIdentifier || undefined,
 70	      });
 71	      setName("");
 72	      setDescription("");
 73	      setResourceIdentifier("");
 74	      setOwnerId("");
 75	      setSelectedId(application.id);
 76	      await refresh("Application created.");
 77	    } catch (createError) {
 78	      setError(formatApiError(createError));
 79	    } finally {
 80	      setBusy(false);
 81	    }
 82	  }
 83	
 84	  const applications = applicationsQuery.data?.applications ?? [];
 85	  const owners = ownersQuery.data;
 86	  const ownerItems =
 87	    ownerType === "user"
 88	      ? (owners?.users ?? []).map((owner) => ({ label: owner.name, value: owner.id }))
 89	      : (owners?.teams ?? []).map((owner) => ({ label: owner.name, value: owner.id }));
 90	
 91	  return (
 92	    <AdminLayout
 93	      activePath="/admin/applications"
 94	      description="Applications define the boundary where assignments, roles, and OIDC clients meet. Access remains explicit: a role grant never creates an assignment."
 95	      eyebrow="Authorization / Applications"
 96	      title="Make every access decision legible."
 97	    >
 98	      <div className="space-y-8">
 99	        <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
100	          <h2 className="text-xl font-semibold text-kumo-strong">New application</h2>
101	          <p className="mt-2 max-w-2xl text-sm leading-6 text-kumo-subtle">
102	            Resource identifiers are immutable. Leave the field empty to generate one from the
103	            current Shui issuer.
104	          </p>
105	          <form className="mt-5 grid gap-4 lg:grid-cols-2" onSubmit={create}>
106	            <Input
107	              id="application-name"
108	              label="Name"
109	              onChange={(event) => setName(event.target.value)}
110	              required
111	              value={name}
112	            />
113	            <Input
114	              id="application-description"
115	              label="Description (optional)"
116	              onChange={(event) => setDescription(event.target.value)}
117	              value={description}
118	            />
119	            <Input
120	              id="application-resource"
121	              label="Resource identifier (optional)"
122	              onChange={(event) => setResourceIdentifier(event.target.value)}
123	              type="url"
124	              value={resourceIdentifier}
125	            />
126	            <Select
127	              items={[
128	                { label: "User", value: "user" },
129	                { label: "Team", value: "team" },
130	              ]}
131	              label="Owner type"
132	              onValueChange={(value) => {
133	                const nextType = value === "team" ? "team" : "user";
134	                setOwnerType(nextType);
135	                setOwnerId("");
136	              }}
137	              value={ownerType}
138	            />
139	            <Select
140	              items={ownerItems}
141	              label="Owner"
142	              onValueChange={(value) => setOwnerId(value ?? "")}
143	              placeholder="Choose an owner"
144	              required
145	              value={ownerId || null}
146	            />
147	            <div className="lg:col-span-2">
148	              <Button aria-busy={busy} disabled={busy || !ownerId} type="submit" variant="primary">
149	                Create application
150	              </Button>
151	            </div>
152	          </form>
153	        </LayerCard>
154	
155	        {applicationsQuery.isLoading || ownersQuery.isLoading ? (
156	          <AdminStatus>Loading applications...</AdminStatus>
157	        ) : null}
158	        {applicationsQuery.isError ? (
159	          <AdminError>{formatApiError(applicationsQuery.error)}</AdminError>
160	        ) : null}
161	        {ownersQuery.isError ? <AdminError>{formatApiError(ownersQuery.error)}</AdminError> : null}
162	        {error ? <AdminError>{error}</AdminError> : null}
163	        {status ? <AdminStatus>{status}</AdminStatus> : null}
164	
165	        <Grid gap="sm" variant="2up">
166	          {applications.map((application) => (
167	            <ApplicationCard
168	              application={application}
169	              key={application.id}
170	              onSelect={() => setSelectedId(application.id)}
171	              selected={selectedId === application.id}
172	            />
173	          ))}
174	        </Grid>
175	        {!applicationsQuery.isLoading && applications.length === 0 ? (
176	          <LayerCard className="bg-kumo-elevated p-6 ring ring-kumo-line">
