  await database.batch([
    database.insert(applications).values({
      id: applicationId,
      name,
      description,
      status: "active",
      disabledAt: null,
      ownerUserPrincipalId: ownership.ownerUserPrincipalId,
      ownerTeamId: ownership.ownerTeamId,
