import { createFileRoute } from "@tanstack/react-router";

import { ApplicationsAdminPage } from "../../components/applications-admin-page";
import { adminRoutePermissions, requireAdminPermission } from "../../lib/admin-routing";

export const Route = createFileRoute("/admin/applications")({
  beforeLoad: ({ context, location }) =>
    requireAdminPermission(context.adminAccess, adminRoutePermissions.applications, location.href),
  component: ApplicationsAdminPage,
});
import type { AdminAccess } from "../server/modules/models";

export const adminRoutePermissions = {
  applications: "applications:read",
  serviceAccounts: "service-accounts:read",
  systemRoles: "system-roles:read",
  teams: "teams:read",
  users: "users:read",
} as const;

export type AdminRoutePermission =
  (typeof adminRoutePermissions)[keyof typeof adminRoutePermissions];

export function hasAdminPermission(access: AdminAccess | undefined, permission: string) {
  return Boolean(access?.permissions.includes("*") || access?.permissions.includes(permission));
}

export function firstAdminPath(access: AdminAccess) {
  if (hasAdminPermission(access, adminRoutePermissions.users)) return "/admin/users" as const;
  if (hasAdminPermission(access, adminRoutePermissions.teams)) return "/admin/teams" as const;
  if (hasAdminPermission(access, adminRoutePermissions.applications)) {
    return "/admin/applications" as const;
  }
  if (hasAdminPermission(access, adminRoutePermissions.serviceAccounts)) {
    return "/admin/service-accounts" as const;
  }
  if (hasAdminPermission(access, adminRoutePermissions.systemRoles)) {
    return "/admin/system-roles" as const;
  }
  return "/admin/users" as const;
}
import { Badge, Banner, Button, Dialog, LinkButton, Sidebar } from "@cloudflare/kumo";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useState, type ReactElement, type ReactNode } from "react";

import { authClient } from "../lib/auth-client";
import { authQueryKeys, sessionQueryOptions } from "../lib/auth-queries";
import { adminAccessQueryOptions } from "../lib/api-query-options";
import { hasAdminPermission } from "../lib/admin-routing";

const navigation = [
  { href: "/admin/users", label: "Users", icon: "users", permission: "users:read" },
  { href: "/admin/teams", label: "Teams", icon: "teams", permission: "teams:read" },
  {
    href: "/admin/applications",
    label: "Applications",
    icon: "applications",
    permission: "applications:read",
  },
  {
    href: "/admin/service-accounts",
    label: "Service accounts",
    icon: "service-accounts",
    permission: "service-accounts:read",
  },
  {
    href: "/admin/system-roles",
    label: "System roles",
    icon: "system-roles",
    permission: "system-roles:read",
  },
] as const;

type AdminIconName = (typeof navigation)[number]["icon"] | "sign-out";

export function AdminLayout({
  activePath,
  children,
  description,
  eyebrow,
  title,
}: Readonly<{
  activePath: (typeof navigation)[number]["href"];
  children: ReactNode;
  description: string;
  eyebrow: string;
  title: string;
}>) {
  const queryClient = useQueryClient();
  const sessionQuery = useQuery(sessionQueryOptions);
  const accessQuery = useQuery(adminAccessQueryOptions);
  const visibleNavigation = navigation.filter((item) =>
    hasAdminPermission(accessQuery.data, item.permission),
  );

  async function signOut() {
    await authClient.signOut();
    await queryClient.invalidateQueries({ queryKey: authQueryKeys.session });
    if (typeof window !== "undefined") window.location.assign("/sign-in");
  }

  return (
    <div className="min-h-screen bg-kumo-canvas">
      <a
        className="sr-only focus:not-sr-only focus:fixed focus:inset-s-4 focus:top-4 focus:z-50 focus:rounded-md focus:bg-kumo-strong focus:px-4 focus:py-3 focus:text-base focus:text-kumo-canvas"
        href="#admin-content"
      >
        Skip to content
      </a>
      <Sidebar.Provider className="h-svh min-h-svh" collapsible="icon" defaultOpen>
        <Sidebar>
          <Sidebar.Header>
            <Sidebar.Menu className="min-w-0 flex-1">
              <Sidebar.MenuButton href="/" icon={<ShuiMark />} tooltip="Shui home">
                SHUI/
              </Sidebar.MenuButton>
            </Sidebar.Menu>
            <Sidebar.Trigger />
          </Sidebar.Header>
          <Sidebar.Content>
            <Sidebar.Group>
              <Sidebar.GroupLabel>Administration</Sidebar.GroupLabel>
              <Sidebar.Menu aria-label="Administration">
                {visibleNavigation.map((item) => (
                  <Sidebar.MenuButton
                    active={item.href === activePath}
                    aria-current={item.href === activePath ? "page" : undefined}
                    href={item.href}
                    icon={<AdminIcon name={item.icon} />}
                    key={item.href}
                    tooltip={item.label}
                  >
                    {item.label}
