          </LayerCard>
        ) : null}

        {selectedId ? (
          <ApplicationDetail
            application={applications.find((application) => application.id === selectedId)}
            owners={owners}
            onRefresh={refresh}
          />
        ) : null}
      </div>
    </AdminLayout>
  );
}

